package com.ludo.trailnav.watch;
import android.content.*;import android.graphics.*;import android.os.*;import android.view.*;import com.ludo.trailnav.core.*;import java.util.*;
public final class TrailMapView extends View{
 private static final int BG=Color.rgb(9,74,45),GREEN=Color.rgb(63,231,137),GRAY=Color.rgb(203,211,206),WHITE=Color.WHITE;private final Paint p=new Paint(Paint.ANTI_ALIAS_FLAG);private final android.content.SharedPreferences prefs;private final Route route;private final float density;private double originLat,originLon,fitEast,fitNorth,centerEast,centerNorth,fitScale=1,zoom=1;private boolean fitted=false,active=false,follow=true,northUp=false,dragging=false,autoFollow=false,bearingReady=false;private double displayBearing=0;private float cx,cy,radius,controlRadius,controlX,controlDy,lastX,lastY;private long lastCenterTap=0;private Runnable sessionMenu;
 public TrailMapView(Context c,Route r){super(c);route=r;prefs=c.getSharedPreferences("hike",0);density=getResources().getDisplayMetrics().density;if(r!=null){originLat=r.points.get(0).lat;originLon=r.points.get(0).lon;}setClickable(true);}
 public void setActive(boolean a){active=a;invalidate();}public void setSessionMenuAction(Runnable r){sessionMenu=r;}public void followLocation(){follow=true;northUp=false;autoFollow=false;bearingReady=false;invalidate();}
 private float dp(float v){return v*density;}private float east(Route.Point q){return(float)(Math.toRadians(q.lon-originLon)*RouteMath.EARTH_M*Math.cos(Math.toRadians(originLat)));}private float north(Route.Point q){return(float)(Math.toRadians(q.lat-originLat)*RouteMath.EARTH_M);}
 private void fit(){if(route==null)return;double minE=1e99,maxE=-1e99,minN=1e99,maxN=-1e99;for(Route.Point q:route.points){double e=east(q),n=north(q);minE=Math.min(minE,e);maxE=Math.max(maxE,e);minN=Math.min(minN,n);maxN=Math.max(maxN,n);}fitEast=(minE+maxE)/2;fitNorth=(minN+maxN)/2;fitScale=Math.min((getWidth()-dp(85))/Math.max(80,maxE-minE),(getHeight()-dp(125))/Math.max(80,maxN-minN));if(!Double.isFinite(fitScale)||fitScale<=0)fitScale=1;if(!fitted){centerEast=fitEast;centerNorth=fitNorth;fitted=true;}}
 private float orientation(){if(northUp)return 0;if(follow&&!autoFollow)return 0;return bearingReady?(float)displayBearing:0;}
 @Override protected void onDraw(Canvas c){super.onDraw(c);int w=getWidth(),h=getHeight();if(w<=0||h<=0)return;cx=w/2f;cy=h/2f;radius=Math.min(w,h)/2f;controlRadius=dp(15.5f);controlDy=dp(30);controlX=radius-controlRadius-dp(22);c.save();Path clip=new Path();clip.addCircle(cx,cy,radius,Path.Direction.CW);c.clipPath(clip);c.drawColor(BG);drawGrid(c);if(route!=null){fit();drawRoute(c);drawInfo(c);if(active)drawControls(c);}c.restore();if(active)postInvalidateDelayed(700);}
 private void drawGrid(Canvas c){p.setStyle(Paint.Style.STROKE);p.setStrokeWidth(dp(.75f));p.setColor(Color.argb(28,121,193,142));for(int i=-3;i<=3;i++){float s=dp(68);c.drawLine(cx+i*s,0,cx+i*s,getHeight(),p);c.drawLine(0,cy+i*s,getWidth(),cy+i*s,p);}p.setStyle(Paint.Style.FILL);}
 private void drawRoute(Canvas c){long fix=prefs.getLong("lastGpsElapsed",0);boolean valid=active&&prefs.getBoolean("gps_valid",false)&&fix>0&&SystemClock.elapsedRealtime()-fix<12000;Route.Point cur=fix>0?new Route.Point(prefs.getFloat("lat",0),prefs.getFloat("lon",0)):null;float progress=Math.min((float)route.meters,Math.max(0,prefs.getFloat("progress",0)));if(valid&&follow){centerEast=east(cur);centerNorth=north(cur);updateAuto(progress);}double sc=fitScale*zoom;float rot=orientation();c.save();float shift=(follow&&valid&&autoFollow)?dp(42):0;c.translate(cx,cy+shift);c.rotate(-rot);c.scale((float)sc,(float)sc);c.translate((float)-centerEast,(float)centerNorth);p.setStyle(Paint.Style.STROKE);p.setStrokeCap(Paint.Cap.ROUND);p.setStrokeJoin(Paint.Join.ROUND);p.setColor(GRAY);p.setStrokeWidth((float)(dp(4.4f)/sc));Path whole=new Path();boolean first=true;for(int i=0;i<route.points.size();i++){Route.Point q=route.points.get(i);if(i>0&&RouteMath.distance(route.points.get(i-1),q)>450)first=true;if(first){whole.moveTo(east(q),-north(q));first=false;}else whole.lineTo(east(q),-north(q));}c.drawPath(whole,p);if(progress>0)drawWalked(c,sc,progress);drawStartFinish(c,sc);if(cur!=null){float x=east(cur),y=-north(cur);p.setStyle(Paint.Style.FILL);p.setColor(valid?Color.argb(80,63,231,137):Color.argb(80,200,200,200));c.drawCircle(x,y,(float)(dp(14)/sc),p);p.setColor(WHITE);c.drawCircle(x,y,(float)(dp(7)/sc),p);p.setColor(valid?GREEN:GRAY);c.drawCircle(x,y,(float)(dp(4.5f)/sc),p);if(prefs.getBoolean("return_mode",false)){Route.Point start=prefs.getBoolean("reverse",false)?route.points.get(route.points.size()-1):route.points.get(0);p.setStyle(Paint.Style.STROKE);p.setColor(GREEN);p.setStrokeWidth((float)(dp(2.2f)/sc));p.setPathEffect(new DashPathEffect(new float[]{(float)(dp(7)/sc),(float)(dp(5)/sc)},0));c.drawLine(x,y,east(start),-north(start),p);p.setPathEffect(null);}}c.restore();p.setStyle(Paint.Style.FILL);if(active){if(!valid)centerText(c,prefs.getBoolean("gps_weak",false)?"GPS WEAK":"WAITING FOR GPS",cy+dp(2),dp(10),Color.rgb(247,198,92));else if(prefs.getBoolean("at_start",false)&&progress<25)centerText(c,"AT TRAIL START",cy+dp(2),dp(10),Color.rgb(156,225,182));else if(prefs.getBoolean("off_trail",false))centerText(c,"OFF TRAIL",cy+dp(35),dp(10),Color.rgb(247,198,92));if(prefs.getBoolean("return_mode",false)&&cur!=null)drawReturn(c,cur);}}
 private void drawWalked(Canvas c,double sc,float prog){boolean rev=prefs.getBoolean("reverse",false);Path walked=new Path();boolean started=false;double prior=0;if(!rev){for(int i=0;i<route.points.size()-1;i++){Route.Point a=route.points.get(i),b=route.points.get(i+1);double len=RouteMath.distance(a,b);if(len>450)continue;if(prior>=prog)break;if(!started){walked.moveTo(east(a),-north(a));started=true;}double f=Math.min(1,Math.max(0,(prog-prior)/Math.max(1e-6,len)));walked.lineTo(east(a)+(east(b)-east(a))*(float)f,-north(a)+(-north(b)+north(a))*(float)f);prior+=len;if(f<1)break;}}else{for(int i=route.points.size()-1;i>0;i--){Route.Point a=route.points.get(i),b=route.points.get(i-1);double len=RouteMath.distance(a,b);if(len>450)continue;if(prior>=prog)break;if(!started){walked.moveTo(east(a),-north(a));started=true;}double f=Math.min(1,Math.max(0,(prog-prior)/Math.max(1e-6,len)));walked.lineTo(east(a)+(east(b)-east(a))*(float)f,-north(a)+(-north(b)+north(a))*(float)f);prior+=len;if(f<1)break;}}p.setColor(GREEN);p.setStrokeWidth((float)(dp(5.1f)/sc));c.drawPath(walked,p);}
 private void drawStartFinish(Canvas c,double sc){Route.Point s=route.points.get(0),f=route.points.get(route.points.size()-1);p.setStyle(Paint.Style.FILL);p.setColor(GREEN);c.drawCircle(east(s),-north(s),(float)(dp(5)/sc),p);p.setColor(WHITE);p.setTextSize((float)(dp(6.7f)/sc));p.setTypeface(android.graphics.Typeface.DEFAULT_BOLD);c.drawText("S",east(s)-p.measureText("S")/2,-north(s)-(p.ascent()+p.descent())/2,p);p.setColor(Color.rgb(247,198,92));float x=east(f),y=-north(f),r=(float)(dp(5)/sc);c.drawRect(x-r,y-r,x+r,y+r,p);}
 private void drawReturn(Canvas c,Route.Point cur){Route.Point s=prefs.getBoolean("reverse",false)?route.points.get(route.points.size()-1):route.points.get(0);double m=RouteMath.distance(cur,s),b=RouteMath.bearing(cur,s);String d=m<160.934?String.format(Locale.US,"%.0f FT",m*3.28084):String.format(Locale.US,"%.2f MI",m/1609.344);centerText(c,"RETURN • "+d+" • "+RouteMath.cardinal(b),cy+dp(58),dp(8.5f),WHITE);}
 private void updateAuto(float progress){if(route.points.size()<2||fitScale<=0)return;if(progress<8||prefs.getBoolean("at_start",false)){autoFollow=false;bearingReady=false;zoom=1;return;}autoFollow=true;double target=headingAt(progress,24);if(!bearingReady){displayBearing=target;bearingReady=true;}else displayBearing=norm(displayBearing+delta(displayBearing,target)*.28);double n=headingAt(progress+10,20),f=headingAt(progress+70,30),turn=Math.abs(delta(n,f));double vis=turn>=70?72:turn>=45?88:turn>=28?108:turn>=15?135:175;double desired=(getHeight()*.58)/Math.max(55,vis),tz=Math.max(2.5,Math.min(32,desired/Math.max(.0001,fitScale)));zoom=zoom*.76+tz*.24;}
 private double headingAt(double prog,double look){Route.Point a=pointAt(prog),b=pointAt(Math.min(route.meters,prog+Math.max(7,look)));return a==null||b==null?0:RouteMath.bearing(a,b);}private Route.Point pointAt(double prog){boolean rev=prefs.getBoolean("reverse",false);prog=Math.max(0,Math.min(route.meters,prog));double walk=0;if(!rev){for(int i=0;i<route.points.size()-1;i++){Route.Point a=route.points.get(i),b=route.points.get(i+1);double l=RouteMath.distance(a,b);if(l>450)continue;if(walk+l>=prog){double f=l<=0?0:(prog-walk)/l;return new Route.Point(a.lat+(b.lat-a.lat)*f,a.lon+(b.lon-a.lon)*f);}walk+=l;}return route.points.get(route.points.size()-1);}for(int i=route.points.size()-1;i>0;i--){Route.Point a=route.points.get(i),b=route.points.get(i-1);double l=RouteMath.distance(a,b);if(l>450)continue;if(walk+l>=prog){double f=l<=0?0:(prog-walk)/l;return new Route.Point(a.lat+(b.lat-a.lat)*f,a.lon+(b.lon-a.lon)*f);}walk+=l;}return route.points.get(0);}
 private static double delta(double a,double b){double d=(b-a)%360;if(d>180)d-=360;if(d<-180)d+=360;return d;}private static double norm(double a){a%=360;if(a<0)a+=360;return a;}
 private void centerText(Canvas c,String s,float y,float size,int color){p.setStyle(Paint.Style.FILL);p.setColor(color);p.setTextSize(size);p.setTypeface(android.graphics.Typeface.create("sans-serif",1));c.drawText(s,cx-p.measureText(s)/2,y,p);}
 private void curvedPill(Canvas c,String text,float inset,float start,float sweep,int color,float fs){float r=radius-inset;RectF o=new RectF(cx-r,cy-r,cx+r,cy+r);Path arc=new Path();arc.addArc(o,start,sweep);p.setStyle(Paint.Style.FILL);p.setTypeface(android.graphics.Typeface.create("sans-serif",1));p.setTextSize(fs);PathMeasure m=new PathMeasure(arc,false);float tw=p.measureText(text),off=Math.max(0,(m.getLength()-tw)/2),pad=dp(5.5f);Path pill=new Path();m.getSegment(Math.max(0,off-pad),Math.min(m.getLength(),off+tw+pad),pill,true);p.setStyle(Paint.Style.STROKE);p.setStrokeCap(Paint.Cap.ROUND);p.setStrokeWidth(dp(12));p.setColor(Color.argb(132,8,28,20));c.drawPath(pill,p);p.setStyle(Paint.Style.FILL);p.setStrokeCap(Paint.Cap.BUTT);p.setColor(color);c.drawTextOnPath(text,arc,off,dp(3),p);}
 private void drawInfo(Canvas c){String n=route.name.length()>30?route.name.substring(0,28)+"…":route.name;curvedPill(c,n.toUpperCase(Locale.US),dp(7),212,116,WHITE,dp(10.2f));curvedPill(c,active?"TRAIL ACTIVE • OFFLINE":"READY • OFFLINE",dp(20),212,116,Color.rgb(156,225,182),dp(8.6f));float prog=Math.min((float)route.meters,Math.max(0,prefs.getFloat("progress",0)));curvedPill(c,String.format(Locale.US,"%.1f / %.1f MI",prog/1609.344,route.meters/1609.344),dp(20),148,-116,WHITE,dp(9.8f));long st=prefs.getLong("startElapsed",0),sec=active&&st>0?Math.max(0,(SystemClock.elapsedRealtime()-st)/1000):0;curvedPill(c,String.format(Locale.US,"%,d STEPS • %02d:%02d:%02d",Math.max(0,prefs.getInt("steps",0)),sec/3600,(sec/60)%60,sec%60),dp(7),148,-116,WHITE,dp(9.7f));}
 private void drawControls(Canvas c){control(c,cx-controlX,cy-controlDy,"+");control(c,cx-controlX,cy+controlDy,"−");control(c,cx+controlX,cy-controlDy,northUp?"N":"↗");control(c,cx+controlX,cy+controlDy,"⌖");}private void control(Canvas c,float x,float y,String t){p.setStyle(Paint.Style.FILL);p.setColor(Color.argb(234,11,37,23));c.drawCircle(x,y,controlRadius,p);p.setStyle(Paint.Style.STROKE);p.setStrokeWidth(dp(1.5f));p.setColor(GREEN);c.drawCircle(x,y,controlRadius,p);p.setStyle(Paint.Style.FILL);p.setColor(WHITE);p.setTypeface(android.graphics.Typeface.create("sans-serif-medium",1));p.setTextSize(dp(t.equals("+")||t.equals("−")?21:18));c.drawText(t,x-p.measureText(t)/2,y-(p.ascent()+p.descent())/2,p);}
 @Override public boolean onTouchEvent(MotionEvent e){if(route==null||!active)return true;float x=e.getX(),y=e.getY();if(e.getAction()==MotionEvent.ACTION_DOWN){lastX=x;lastY=y;dragging=false;return true;}if(e.getAction()==MotionEvent.ACTION_MOVE){float dx=x-lastX,dy=y-lastY;if(Math.hypot(dx,dy)>dp(2)){dragging=true;follow=false;double a=Math.toRadians(orientation()),sc=Math.max(.01,fitScale*zoom);centerEast-=(Math.cos(a)*dx-Math.sin(a)*dy)/sc;centerNorth+=(Math.sin(a)*dx+Math.cos(a)*dy)/sc;invalidate();}lastX=x;lastY=y;return true;}if(e.getAction()==MotionEvent.ACTION_UP){if(dragging)return true;if(Math.abs(x-(cx-controlX))<=controlRadius+dp(11)){if(Math.abs(y-(cy-controlDy))<=controlRadius+dp(10)){zoom=Math.min(40,zoom*1.55);follow=false;invalidate();return true;}if(Math.abs(y-(cy+controlDy))<=controlRadius+dp(10)){zoom=Math.max(1,zoom/1.55);follow=false;invalidate();return true;}}if(Math.abs(x-(cx+controlX))<=controlRadius+dp(11)){if(Math.abs(y-(cy-controlDy))<=controlRadius+dp(10)){northUp=!northUp;invalidate();return true;}if(Math.abs(y-(cy+controlDy))<=controlRadius+dp(10)){followLocation();return true;}}if(Math.hypot(x-cx,y-cy)<=dp(78)){long now=SystemClock.elapsedRealtime();if(lastCenterTap>0&&now-lastCenterTap<=380){lastCenterTap=0;if(sessionMenu!=null)sessionMenu.run();}else lastCenterTap=now;return true;}return true;}return true;}
}
